INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(33911, 'Romans 6:1', 'Romans', 6, 1, 'نو بیا مونږ څه ووایو؟ ایا باید خپل ژوند ته په ګناهونو کې دوام ورکړو، ترڅو د خدای فضل زیات شي؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_1.mp3', '', 1761754199, 1761754199),
(33912, 'Romans 6:2', 'Romans', 6, 2, 'هېڅکله نه! مونږ چې د ګناه په وړاندې مړه یو، نو بیا څنګه کولای شو چې په ګناه کې خپل ژوند ته دوام ورکړو؟', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_2.mp3', '', 1761754199, 1761754199),
(33913, 'Romans 6:3', 'Romans', 6, 3, 'ایا تاسو نه پوهېږئ کله چې مونږ ټولو په عیسی مسیح کې د تعمید غسل واخیست، نو د هغه په مرګ کې ورسره شریک شولو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_3.mp3', '', 1761754199, 1761754199),
(33914, 'Romans 6:4', 'Romans', 6, 4, 'نو مونږ د خپل تعمید په وسیله د هغه سره ښخ شولو او ورسره مړه شولو. لکه څنګه چې مسیح د پلار په جلال کې د مړو نه راژوندی شو، نو مونږ به هم نوی ژوند ولرو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_4.mp3', '', 1761754199, 1761754199),
(33915, 'Romans 6:5', 'Romans', 6, 5, 'ځکه که چېرې مونږ د مسیح په مرګ کې ورسره شریک شولو، نو په هماغه ډول به د هغه په بیا راژوندي کېدلو کې هم د هغه سره شریک شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_5.mp3', '', 1761754199, 1761754199),
(33916, 'Romans 6:6', 'Romans', 6, 6, 'مونږ پوهېږو چې زمونږ زوړ فطرت د مسیح سره په صلیب کې مړ شو، ترڅو ګناه زمونږ په ژوند باندې خپل قدرت له لاسه ورکړي او مونږ نور د ګناه غلامان ونه اوسو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_6.mp3', '', 1761754199, 1761754199),
(33917, 'Romans 6:7', 'Romans', 6, 7, 'ځکه څوک چې مړ شي، نو هغه د ګناه نه خلاص شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_7.mp3', '', 1761754199, 1761754199),
(33918, 'Romans 6:8', 'Romans', 6, 8, 'که چېرې مونږ د مسیح سره مړه شوي یو، نو په دې ایمان لرو چې د هغه سره به ژوند هم کوو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_8.mp3', '', 1761754199, 1761754199),
(33919, 'Romans 6:9', 'Romans', 6, 9, 'ځکه مونږ پوهېږو چې مسیح د مړو نه راژوندی شوی دی او بیا به هېڅکله مړ نه شي، یعنې مرګ نور په هغه باندې واک او اختیار نه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_9.mp3', '', 1761754199, 1761754199),
(33920, 'Romans 6:10', 'Romans', 6, 10, 'کله چې مسیح مړ شو، نو هغه یوځل او د تل دپاره د ګناهونو په خاطر مړ شو. خو اوس چې هغه ژوندی دی، نو هغه یوازې د خدای دپاره ژوند کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_10.mp3', '', 1761754199, 1761754199),
(33921, 'Romans 6:11', 'Romans', 6, 11, 'نو تاسو هم خپل ځانونه د ګناه په وړاندې مړه وګڼئ، خو د خدای په وړاندې د عیسی مسیح سره په یووالي کې خپل ځانونه ژوندي وګڼئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_11.mp3', '', 1761754199, 1761754199),
(33922, 'Romans 6:12', 'Romans', 6, 12, 'نو مه پرېږدئ چې ګناه نور ستاسو په فاني بدن باندې حکومت وکړي او تاسو د خپلو نفساني غوښتنو تابع کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_12.mp3', '', 1761754199, 1761754199),
(33923, 'Romans 6:13', 'Romans', 6, 13, 'د خپل بدن یو غړی هم د یوې وسیلې په توګه د بدۍ په اختیار کې مه ورکوئ، بلکې خپل ځانونه خدای ته وسپارئ او د هغو کسانو په شان چې د مرګ نه راژوندي شوي دي، د خپل بدن غړي خدای ته د عدالت او رښتینولۍ دپاره د یوې وسیلې په توګه وړاندې کړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_13.mp3', '', 1761754199, 1761754199),
(33924, 'Romans 6:14', 'Romans', 6, 14, 'ځکه چې ګناه به نور په تاسو باندې حاکمه نه وي، له دې امله چې تاسو نور د شریعت تابع نه یئ، بلکې د خدای د فضل لاندې یئ. د عدالت غلامان', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_14.mp3', '', 1761754199, 1761754199),
(33925, 'Romans 6:15', 'Romans', 6, 15, 'نو بیا څه ووایو؟ ایا مونږ باید ګناه وکړو، ځکه چې د شریعت تابع نه یو، بلکې د خدای د فضل لاندې یو؟ نه، هېڅکله نه!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_15.mp3', '', 1761754199, 1761754199),
(33926, 'Romans 6:16', 'Romans', 6, 16, 'ایا تاسو نه پوهېږئ چې که چېرې تاسو خپل ځانونه د غلامانو په توګه د کوم چا په اختیار کې ورکړئ او د هغه تابع اوسئ، نو په حقیقت کې تاسو د هغه چا غلامان یئ چې اطاعت یې کوئ، که هغه د ګناه غلامي وي چې پای یې مرګ دی او یا د خدای تابعداري وي چې نتیجه یې عدالت دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_16.mp3', '', 1761754199, 1761754199),
(33927, 'Romans 6:17', 'Romans', 6, 17, 'نو د خدای شکر دی چې تاسو یو وخت د ګناه غلامان وئ، خو اوس تاسو د زړه له اخلاصه د هغه تعلیم اطاعت کوئ چې تاسو ته درکړل شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_17.mp3', '', 1761754199, 1761754199),
(33928, 'Romans 6:18', 'Romans', 6, 18, 'اوس تاسو د ګناه نه ازاد او د عدالت غلامان شوي یئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_18.mp3', '', 1761754199, 1761754199),
(33929, 'Romans 6:19', 'Romans', 6, 19, 'زه ستاسو د انساني فطرت د کمزورۍ له امله ساده خبرې کوم. لکه څنګه چې تاسو یو وخت خپل ځانونه د ناپاکۍ او د ټولو بدو کارونو غلامان کړي وو، نو اوس خپل د بدن ټول غړي د عدالت غلامان کړئ چې پاک او سپېڅلي شئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_19.mp3', '', 1761754199, 1761754199),
(33930, 'Romans 6:20', 'Romans', 6, 20, 'کله چې تاسو د ګناه غلامان وئ، نو مجبوره نه وئ چې عدالت او رښتینولي وکړئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_20.mp3', '', 1761754199, 1761754199),
(33931, 'Romans 6:21', 'Romans', 6, 21, 'د هغو کارونو په کولو سره چې اوس ورباندې شرمېږئ تاسو کومه ګټه تر‌لاسه کړه؟ ځکه چې د هغو کارونو پای مرګ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_21.mp3', '', 1761754199, 1761754199),
(33932, 'Romans 6:22', 'Romans', 6, 22, 'خو اوس تاسو د ګناه نه ازاد شوي یئ او د خدای غلامان یئ. د دې ګټه دا ده چې تاسو پاک او سپېڅلي شوي یئ او د دې نتیجه تلپاتې ژوندون دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_22.mp3', '', 1761754199, 1761754199),
(33933, 'Romans 6:23', 'Romans', 6, 23, 'ځکه چې د ګناه نتیجه مرګ دی، خو د خدای نعمت زمونږ په څښتن عیسی مسیح کې تلپاتې ژوندون دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans6_verse_23.mp3', '', 1761754199, 1761754199),
(33934, 'Acts 4:1', 'Acts', 4, 1, 'پطروس او یوحنا لا د خلکو سره خبرې کولې چې په دې وخت کې ځینې کاهنان، د خدای د کور د ساتونکو قوماندان او ځینې صدوقیان راورسېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_1.mp3', '', 1761754199, 1761754199),
(33935, 'Acts 4:2', 'Acts', 4, 2, 'هغوی ډېر په قهر وو، ځکه چې رسولانو خلکو ته تعلیم ورکاوه او اعلان یې کاوه چې عیسی د مړو څخه بیا راژوندی شوی دی او دا ثابتوي چې مړي به راژوندي کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_2.mp3', '', 1761754199, 1761754199),
(33936, 'Acts 4:3', 'Acts', 4, 3, 'هغوی پطروس او یوحنا ونیول، خو له دې امله چې ماښام ؤ، نو هغوی یې تر سبا ورځې پورې په زندان کې وساتل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_3.mp3', '', 1761754199, 1761754199),
(33937, 'Acts 4:4', 'Acts', 4, 4, 'خو ډېرو خلکو چې دا پیغام واورېد، نو ایمان یې راوړ. د هغوی شمېر نژدې پنځو زرو کسانو ته ورسېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_4.mp3', '', 1761754199, 1761754199),
(33938, 'Acts 4:5', 'Acts', 4, 5, 'بله ورځ د یهودیانو حاکمان، مشران او د شریعت عالمان په اورشلیم کې سره راټول شول.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_5.mp3', '', 1761754199, 1761754199),
(33939, 'Acts 4:6', 'Acts', 4, 6, 'لوی کاهن حناس او قیافا، یوحنا، سکندر او د لوی کاهن د کورنۍ نور غړي هم هلته وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_6.mp3', '', 1761754199, 1761754199),
(33940, 'Acts 4:7', 'Acts', 4, 7, 'هغوی پطروس او یوحنا راوستل او د شورا په مخکې یې ودرول او پوښتنه یې ترې وکړه: «تاسو په کوم قدرت او د چا په نوم دا کار کړی دی؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_7.mp3', '', 1761754199, 1761754199),
(33941, 'Acts 4:8', 'Acts', 4, 8, 'پطروس چې د روح القدس څخه ډک شو، هغوی ته ځواب ورکړ: «ای د قوم حاکمانو او مشرانو:', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_8.mp3', '', 1761754199, 1761754199),
(33942, 'Acts 4:9', 'Acts', 4, 9, 'که چېرې تاسو نن زمونږ څخه د هغه نېک کار په هکله چې د هغه شل سړي سره مو کړی دی پوښتنه کوئ او غواړئ په دې پوه شئ چې هغه څنګه روغ شو،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_9.mp3', '', 1761754199, 1761754199),
(33943, 'Acts 4:10', 'Acts', 4, 10, 'نو تاسو ټول او د اسراییلو ټول قوم دې په دې پوه شي چې دا سړی چې ستاسو په مخکې ولاړ دی، هغه د ناصري عیسی مسیح د نوم په قدرت سره چې تاسو په صلیب ځوړند کړ او خدای بېرته د مړو څخه راژوندی کړ، روغ شوی دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_10.mp3', '', 1761754199, 1761754199),
(33944, 'Acts 4:11', 'Acts', 4, 11, 'عیسی هغه څوک دی چې د هغه په هکله د خدای په کلام کې لیکل شوي دي: کومه تیږه چې رد کړې ګلکارانو وه هغه اوس شوه اصلي تیږه د تهداب', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_11.mp3', '', 1761754199, 1761754199),
(33945, 'Acts 4:12', 'Acts', 4, 12, 'خلاصون یوازې د عیسی په وسیله تر‌لاسه کېدای شي. ځکه چې په ټوله نړۍ کې بل داسې څوک نشته چې د هغه په وسیله مونږ خلاصون ومومو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_12.mp3', '', 1761754199, 1761754199),
(33946, 'Acts 4:13', 'Acts', 4, 13, 'کله چې هغوی د پطروس او یوحنا زړورتیا ولیدله او پوه شول چې هغوی عادي او بې‌تعلیمه خلک دي، نو حیران شول او ویې وپېژندل چې د عیسی ملګري دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_13.mp3', '', 1761754199, 1761754199),
(33947, 'Acts 4:14', 'Acts', 4, 14, 'خو څرنګه چې هغوی هغه سړی ولیده چې روغ رمټ د هغوی په منځ کې ولاړ دی، نو هېڅ یې ونه شو ویلی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_14.mp3', '', 1761754199, 1761754199),
(33948, 'Acts 4:15', 'Acts', 4, 15, 'نو هغوی پطروس او یوحنا ته امر وکړ چې د شورا څخه ووځي او بیا یې په خپل منځ کې بحث پیل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_15.mp3', '', 1761754199, 1761754199),
(33949, 'Acts 4:16', 'Acts', 4, 16, 'هغوی وویل: «دې خلکو سره څه وکړو؟ ځکه چې د اورشلیم ټول خلک پوهیږي چې دا حیرانوونکې معجزه د هغوی له خوا وشوه او مونږ له هغې څخه منکرېدلی نه شو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_16.mp3', '', 1761754199, 1761754199),
(33950, 'Acts 4:17', 'Acts', 4, 17, 'خو د دې دپاره چې دا خبره نوره هم د خلکو په منځ کې خپره نه شي، نو هغوی ته باید خبرداری ورکړو چې نور د عیسی په هکله د هېچا سره خبرې ونه کړي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts4_verse_17.mp3', '', 1761754199, 1761754199),
